r"""Re-creates build65.py + merge_final.json from the v6.4 originals (read-only inputs).
Run: py -3.11 -X utf8 make_vendor.py   (cwd anywhere)"""
import hashlib
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
SRC = r"C:\00000ConvergenceER\ClaudeWorkspace\clever_x_convergence_x_mckenyu_INF_DURATIONS\v64\work\build64.py"
MF = r"C:\00000ConvergenceER\ClaudeWorkspace\clever_x_convergence_x_mckenyu_INF_DURATIONS\v64\work\merge_final.json"
t = open(SRC, encoding="utf-8").read()
smd5 = hashlib.md5(open(SRC, "rb").read()).hexdigest()
mmd5 = hashlib.md5(open(MF, "rb").read()).hexdigest()


def sub(old, new):
    global t
    assert t.count(old) == 1, (old, t.count(old))
    t = t.replace(old, new)


HDR = [
    '"""VENDORED PORT for the v6.5 installer pipeline (v65/installer/pipeline/vendor/infdur/build65.py).',
    "Copy of clever_x_convergence_x_mckenyu_INF_DURATIONS/v64/work/build64.py (md5 %s), changed ONLY in:" % smd5,
    "  * FW   = v65/opus/work (the v6.5 framework) instead of v64/opus/work;",
    "  * RUNS = v65/installer/work/infdur (the build64.py run folder is a v64 folder: never written);",
    "  * merge_final.json = the copy next to this file (v64 md5 %s + SpEffect 800000711, a byte copy" % mmd5,
    "    of 800000710 added by v6.5 F64d R7, same category aow_weapon_buff);",
    "  * --ver default V6.5.",
    "Everything else (selection, isEnhance rule, container handling, verification) is unchanged.",
    "Generated by make_vendor.py.",
    "",
    "",
]
sub('"""Build the four Infinite-Durations add-ons', "\n".join(HDR) + "Build the four Infinite-Durations add-ons")
sub(r'FW = WS + r"\clever_x_convergence_x_mckenyu\v64\opus\work"          # v6.4 framework (read-only use)',
    r'FW = WS + r"\clever_x_convergence_x_mckenyu\v65\opus\work"          # v6.5 framework (read-only use)')
sub('RUNS = os.path.join(V64, "_runs")',
    r'RUNS = WS + r"\clever_x_convergence_x_mckenyu\v65\installer\work\infdur"   # v6.5 pipeline run folder')
sub('ap.add_argument("--ver", default="V6.4", help="version label used in names and changelog")',
    'ap.add_argument("--ver", default="V6.5", help="version label used in names and changelog")')
open(os.path.join(HERE, "build65.py"), "w", encoding="utf-8", newline="\n").write(t)

m = json.load(open(MF))
out = []
for c in m:
    out.append(c)
    if c["id"] == 800000710:
        d = dict(c)
        d["id"] = 800000711
        out.append(d)
assert len(out) == len(m) + 1, "800000710 not found in merge_final.json"
json.dump(out, open(os.path.join(HERE, "merge_final.json"), "w"), indent=1)
open(os.path.join(HERE, "VENDOR.txt"), "w").write(
    "build65.py <- %s (md5 %s)\nmerge_final.json <- %s (md5 %s) + SpEffect 800000711 (copy of 800000710's entry)\n"
    "Re-create with: py -3.11 -X utf8 make_vendor.py\n" % (SRC, smd5, MF, mmd5))
print("vendored", smd5, mmd5)
